"""Every setting and screen constant in one place. tools/make_settings_dvdlogo.py turns the
table into settings.xml and strings.po; read() loads values with the right types and defaults.
No Kodi imports.
"""

ADDON_ID = 'screensaver.dvdlogo'

# The skin's coordinate system, as in the other screensavers here.
W, H = 1920, 1080

# dvd.png is generated by tools/make_dvd_media.py; tests/test_dvdlogo.py checks these sizes.
LOGO_W, LOGO_H = 459, 210
LOGO_ASPECT = LOGO_W / float(LOGO_H)

BASE_SPEED = 200.0          # pixels per second on a 1920x1080 screen at Speed 100%
FIRST_TRY_SECONDS = 4.0     # the first corner trick comes this soon after the screensaver starts

# Corner trick modes.
BOUNCE, HIT, MISS, ALTERNATE = 0, 1, 2, 3

COLOUR_WHITE, COLOUR_BOUNCE, COLOUR_CORNER, COLOUR_RAINBOW, COLOUR_FIXED = 0, 1, 2, 3, 4


def B(sid, label, default, **kw):
    return dict(id=sid, type='boolean', label=label, default=default, **kw)


def O(sid, label, default, options, **kw):
    return dict(id=sid, type='options', label=label, default=default, options=options, **kw)


def S(sid, label, default, lo, hi, step=1, **kw):
    return dict(id=sid, type='slider', label=label, default=default, min=lo, max=hi, step=step, **kw)


def C(sid, label, default, **kw):
    return dict(id=sid, type='colour', label=label, default=default, **kw)


CATEGORIES = [
    ('Logo', [
        S('size', 'Logo size (% of the screen height)', 18, 8, 40, 1),
        S('speed', 'Speed (%)', 100, 20, 300, 10),
        O('colour_mode', 'Colour', COLOUR_CORNER,
          ['White (as pictured)', 'Change colour on every bounce', 'Change colour on corner hits',
           'Slowly cycle through the rainbow', 'Fixed colour']),
        C('colour', 'Fixed colour', 'FFFFFFFF', visible=('colour_mode', '4')),
        C('background', 'Background colour', 'FF000000'),
    ]),
    ('Corners', [
        O('trick', 'Corner trick', ALTERNATE,
          ['Off: just bounce', 'Hit the corner', 'Veer off at the last second',
           'Hit the corner, then veer off the next time']),
        S('trick_every', 'Try a corner no more often than every (seconds)', 10, 5, 120, 5,
          visible=('trick', '!', '0')),
    ]),
]


def all_settings():
    for _title, settings in CATEGORIES:
        for s in settings:
            if s['type'] not in ('action', 'group'):
                yield s


def valid_colour(value):
    v = (value or '').strip().lstrip('#').upper()
    if len(v) == 6:
        v = 'FF' + v
    try:
        int(v, 16)
    except ValueError:
        return None
    return v if len(v) == 8 else None


def read(getters):
    """Settings as a dict. getters: {'boolean': f(id), 'integer': f(id), 'string': f(id)}
    (the Kodi layer passes Addon accessors). Bad or missing values fall back to defaults."""
    out = {}
    for s in all_settings():
        try:
            if s['type'] == 'boolean':
                out[s['id']] = bool(getters['boolean'](s['id']))
            elif s['type'] == 'colour':
                out[s['id']] = valid_colour(getters['string'](s['id'])) or s['default']
            else:
                value = int(getters['integer'](s['id']))
                if s['type'] == 'options' and not 0 <= value < len(s['options']):
                    value = s['default']
                if s['type'] == 'slider':
                    value = min(s['max'], max(s['min'], value))
                out[s['id']] = value
        except Exception:
            out[s['id']] = s['default']
    return out


def defaults():
    return dict((s['id'], s['default']) for s in all_settings())


def logo_pixels(s):
    """(width, height) of the logo on screen."""
    height = int(round(H * s['size'] / 100.0))
    return int(round(height * LOGO_ASPECT)), height


def speed_pixels(s):
    return BASE_SPEED * s['speed'] / 100.0
